files.desk.d.ts:
/** A desk and what is on it. Ask before you move anything. */
declare const desk: {
  /** The lamps on the desk. @read */
  lamps(): Promise<Lamp[]>;
  /** The desk as it looks now. @read */
  snapshot(): Promise<Image>;
  settings: {
    /** Changes the desk's settings; a field left out keeps its value. @write @throws invalid */
    set(patch: { theme?: "light" | "dark" }): Promise<null>;
  };
  /** Shows the person a note. @effect */
  notify(text: string): Promise<null>;
  /** Asks the person, and waits for their answer. @effect @waits @once @throws declined */
  ask(question: string, choices?: string[]): Promise<string>;
};
interface Lamp { id: string; on: boolean }
interface Kinds {
  /** The request is what the person wants done to the desk. @allow desk.* */
  tidy(request: { ask: Instruction }): { summary: string };
}

